// src/components/ChatSidebar.js
import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ currentUser, setSelectedConversation }) => {
  const [conversations, setConversations] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);

  useEffect(() => {
    const fetchConversations = async () => {
      if (!currentUser?.userId) return;
      try {
        const res = await axios.get(`http://localhost:5000/api/conversations/${currentUser.userId}`);
        setConversations(res.data);
        console.log("✅ Fetched conversations:", res.data);
      } catch (err) {
        console.error("❌ Error fetching conversations:", err);
      }
    };

    fetchConversations();
  }, [currentUser]);

  const handleSearch = async (e) => {
    const value = e.target.value;
    setSearchTerm(value);
    if (!value.trim()) {
      setSearchResults([]);
      return;
    }

    try {
      const res = await axios.get(`http://localhost:5000/api/profile/search?username=${value}`);
      const filtered = res.data.filter((u) => u._id !== currentUser.userId);
      setSearchResults(filtered);
    } catch (err) {
      console.error("❌ Error searching users:", err);
    }
  };

  const startConversation = async (otherUser) => {
    try {
      const res = await axios.post("http://localhost:5000/api/conversations", {
        senderId: currentUser.userId,
        receiverId: otherUser._id,
      });

      setSearchTerm("");
      setSearchResults([]);
      setSelectedConversation(res.data);
    } catch (err) {
      console.error("❌ Error starting conversation:", err);
    }
  };

  return (
    <div className="chat-sidebar">
      <input
        className="chat-search"
        type="text"
        placeholder="Search users..."
        value={searchTerm}
        onChange={handleSearch}
      />

      {searchResults.length > 0 && (
        <ul className="search-results">
          {searchResults.map((user) => (
            <li key={user._id} onClick={() => startConversation(user)}>
              {user.username}
            </li>
          ))}
        </ul>
      )}

      <h3>Messages</h3>
      {conversations.length === 0 ? (
        <p>No conversations found.</p>
      ) : (
        <ul className="conversation-list">
          {conversations.map((c) => {
            const otherUsername = c.participantUsernames.find((u) => u !== currentUser.username);
            return (
              <li key={c._id} onClick={() => setSelectedConversation(c)}>
                <strong>{otherUsername}</strong>
                <br />
                <span>{c.lastMessage}</span>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
};

export default ChatSidebar;
